// ১. ওয়েব অ্যাপ এন্ট্রি পয়েন্ট (doGet)
function doGet(e) {
  try {
    autoSetupSheets();
  } catch (err) {
    Logger.log('Setup error: ' + err.toString());
  }

  var action = (e && e.parameter && e.parameter.action) ? e.parameter.action : '';
  
  // API: ওয়েবসাইট থেকে নোটিশের তালিকা চাওয়া
  if (action === 'getNotices' || (e && e.parameter && e.parameter.format === 'json')) {
    var notices = getNoticesList();
    return ContentService
      .createTextOutput(JSON.stringify(notices))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট থেকে পিডিএফ নোট ও বইয়ের তালিকা চাওয়া
  if (action === 'getMaterials') {
    var materials = getMaterialsList();
    return ContentService
      .createTextOutput(JSON.stringify(materials))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট থেকে ছুটির ক্যালেন্ডার ও কনফিগারেশন চাওয়া
  if (action === 'getCalendar') {
    var calData = getCalendarData();
    return ContentService
      .createTextOutput(JSON.stringify(calData))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট বা এডমিন থেকে সরাসরি নোটিশ যোগ করা
  if (action === 'addNotice') {
    var noticeRes = addNoticeFromApi(e.parameter);
    return ContentService
      .createTextOutput(JSON.stringify(noticeRes))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট বা এডমিন থেকে ছুটির তারিখ যোগ করা
  if (action === 'addHoliday') {
    var holRes = addHolidayFromApi(e.parameter);
    return ContentService
      .createTextOutput(JSON.stringify(holRes))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ক্যালেন্ডার কনফিগারেশন আপডেট (ছুটির বার ও ভবিষ্যৎ মাস লক)
  if (action === 'updateConfig') {
    var cfgRes = updateCalendarConfigFromApi(e.parameter);
    return ContentService
      .createTextOutput(JSON.stringify(cfgRes))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট বা এডমিন থেকে নতুন স্টাডি মেটেরিয়াল / পিডিএফ যোগ করা
  if (action === 'addMaterial') {
    var matRes = addMaterialFromApi(e.parameter);
    return ContentService
      .createTextOutput(JSON.stringify(matRes))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // API: ওয়েবসাইট থেকে শিক্ষার্থী সাবস্ক্রাইব করার রিকোয়েস্ট
  if (action === 'addSubscriber') {
    var name = e.parameter.name || 'শিক্ষার্থী';
    var email = e.parameter.email || '';
    var studentId = e.parameter.studentId || '';
    var res = addSubscriberFromAdmin(name, email, studentId);
    return ContentService
      .createTextOutput(JSON.stringify(res))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // ব্রাউজার ভিজিটরদের জন্য সম্পূর্ণ স্বয়ংসম্পূর্ণ ওয়েব অ্যাপ ড্যাশবোর্ড
  return HtmlService
    .createHtmlOutput(getDashboardHtml())
    .setTitle('নোটিশ ও নোট ড্যাশবোর্ড - রাষ্ট্রবিজ্ঞান বিভাগ (DCU)')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL)
    .addMetaTag('viewport', 'width=device-width, initial-scale=1.0');
}

// ১.১. POST মেথড হ্যান্ডলার (বিকল্প রিকোয়েস্ট ও ব্রাউজার ফ্যালব্যাক)
function doPost(e) {
  try {
    autoSetupSheets();
    var params = {};
    if (e && e.postData && e.postData.contents) {
      try {
        params = JSON.parse(e.postData.contents);
      } catch (err) {
        params = e.parameter || {};
      }
    } else if (e && e.parameter) {
      params = e.parameter;
    }

    var action = params.action || '';
    if (action === 'addNotice') {
      var nRes = addNoticeFromApi(params);
      return ContentService.createTextOutput(JSON.stringify(nRes)).setMimeType(ContentService.MimeType.JSON);
    }
    if (action === 'addHoliday') {
      var hRes = addHolidayFromApi(params);
      return ContentService.createTextOutput(JSON.stringify(hRes)).setMimeType(ContentService.MimeType.JSON);
    }
    if (action === 'updateConfig') {
      var cRes = updateCalendarConfigFromApi(params);
      return ContentService.createTextOutput(JSON.stringify(cRes)).setMimeType(ContentService.MimeType.JSON);
    }
    if (action === 'addMaterial') {
      var mRes = addMaterialFromApi(params);
      return ContentService.createTextOutput(JSON.stringify(mRes)).setMimeType(ContentService.MimeType.JSON);
    }
    if (action === 'addSubscriber') {
      var sRes = addSubscriberFromAdmin(params.name, params.email, params.studentId);
      return ContentService.createTextOutput(JSON.stringify(sRes)).setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({ success: true, message: 'অনুরোধ গৃহীত হয়েছে।' }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (postErr) {
    return ContentService.createTextOutput(JSON.stringify({ success: false, error: postErr.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}


// ২. স্বয়ংক্রিয়ভাবে শিট ও কলাম তৈরি (Auto Initialization)
function autoSetupSheets() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  if (!ss) return;

  // Notices শিট তৈরি
  var noticeSheet = ss.getSheetByName('Notices');
  if (!noticeSheet) {
    noticeSheet = ss.insertSheet('Notices');
    var noticeHeaders = [['ID', 'শিরোনাম', 'তারিখ', 'ক্যাটাগরি', 'বিস্তারিত বিবরণ', 'ইমেইল স্ট্যাটাস']];
    noticeSheet.getRange(1, 1, 1, 6).setValues(noticeHeaders);
    noticeSheet.getRange(1, 1, 1, 6)
      .setBackground('#18181b')
      .setFontColor('#f59e0b')
      .setFontWeight('bold')
      .setHorizontalAlignment('center');
    noticeSheet.setFrozenRows(1);
    noticeSheet.setColumnWidth(1, 120);
    noticeSheet.setColumnWidth(2, 260);
    noticeSheet.setColumnWidth(3, 100);
    noticeSheet.setColumnWidth(4, 120);
    noticeSheet.setColumnWidth(5, 380);
    noticeSheet.setColumnWidth(6, 180);
  }

  // Materials (পিডিএফ নোট ও বই) শিট তৈরি
  var matSheet = ss.getSheetByName('Materials');
  if (!matSheet) {
    matSheet = ss.insertSheet('Materials');
    var matHeaders = [['ID', 'কোর্স কোড', 'শিরোনাম', 'ক্যাটাগরি', 'লেখক/সংগ্রাহক', 'ড্রাইভ লিংক', 'সাইজ']];
    matSheet.getRange(1, 1, 1, 7).setValues(matHeaders);
    matSheet.getRange(1, 1, 1, 7)
      .setBackground('#064e3b')
      .setFontColor('#34d399')
      .setFontWeight('bold')
      .setHorizontalAlignment('center');
    matSheet.setFrozenRows(1);
    matSheet.setColumnWidth(1, 120);
    matSheet.setColumnWidth(2, 100);
    matSheet.setColumnWidth(3, 260);
    matSheet.setColumnWidth(4, 120);
    matSheet.setColumnWidth(5, 140);
    matSheet.setColumnWidth(6, 320);
    matSheet.setColumnWidth(7, 90);
  }

  // Subscribers শিট তৈরি
  var subSheet = ss.getSheetByName('Subscribers');
  if (!subSheet) {
    subSheet = ss.insertSheet('Subscribers');
    var subHeaders = [['নাম', 'ইমেইল', 'রোল/আইডি', 'নিবন্ধনের তারিখ']];
    subSheet.getRange(1, 1, 1, 4).setValues(subHeaders);
    subSheet.getRange(1, 1, 1, 4)
      .setBackground('#0f172a')
      .setFontColor('#38bdf8')
      .setFontWeight('bold')
      .setHorizontalAlignment('center');
    subSheet.setFrozenRows(1);
    subSheet.setColumnWidth(1, 180);
    subSheet.setColumnWidth(2, 250);
    subSheet.setColumnWidth(3, 120);
    subSheet.setColumnWidth(4, 120);
  }

  // Calendar (ছুটি ও একাডেমিক ক্যালেন্ডার) শিট তৈরি
  var calSheet = ss.getSheetByName('Calendar');
  if (!calSheet) {
    calSheet = ss.insertSheet('Calendar');
    var calHeaders = [['শুরুর তারিখ (YYYY-MM-DD)', 'শেষের তারিখ (ঐচ্ছিক)', 'স্ট্যাটাস (ছুটি/খোলা/পরীক্ষা)', 'ছুটি বা উপলক্ষের বিবরণ']];
    calSheet.getRange(1, 1, 1, 4).setValues(calHeaders);
    calSheet.getRange(1, 1, 1, 4)
      .setBackground('#7f1d1d')
      .setFontColor('#fecaca')
      .setFontWeight('bold')
      .setHorizontalAlignment('center');
    calSheet.setFrozenRows(1);
    calSheet.setColumnWidth(1, 160);
    calSheet.setColumnWidth(2, 160);
    calSheet.setColumnWidth(3, 160);
    calSheet.setColumnWidth(4, 300);

    // Sheet is initialized clean with headers only - user will add custom holidays from sheet
  }
}

// তারিখ ছোট করে ফরম্যাট করা (যেমন: 9 OCT, 10 OCT)
function formatShortDate(d) {
  if (!d) return '';
  var months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  if (d instanceof Date) {
    return d.getDate() + ' ' + months[d.getMonth()];
  }
  var parsed = new Date(d);
  if (!isNaN(parsed.getTime())) {
    return parsed.getDate() + ' ' + months[parsed.getMonth()];
  }
  var s = String(d).trim();
  var m = s.match(/([0-9]{1,2})\\s+([A-Za-z]{3})/);
  if (m) return m[1] + ' ' + m[2].toUpperCase();
  return s.replace(/\\s*\\(.*?Standard Time.*?\\)/gi, '')
          .replace(/\\s*\\(.*?Bangladesh.*?\\)/gi, '')
          .replace(/\\s*GMT[+-]\\d{4}/gi, '')
          .trim();
}

// ৩. বর্তমান নোটিশের তালিকা রিটার্ন করা
function getNoticesList() {
  try {
    autoSetupSheets();
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) return [];
    var sheet = ss.getSheetByName('Notices');
    if (!sheet) return [];
    var lastRow = sheet.getLastRow();
    if (lastRow <= 1) return [];

    var data = sheet.getRange(2, 1, lastRow - 1, 6).getValues();
    var notices = [];

    for (var i = 0; i < data.length; i++) {
      var row = data[i];
      var title = row[1] ? String(row[1]).trim() : '';
      if (title) {
        notices.push({
          rowIndex: i + 2,
          id: String(row[0] || ('notice-' + (i + 1))),
          title: String(title),
          date: formatShortDate(row[2]),
          category: String(row[3] || 'সাধারণ নোটিশ'),
          content: String(row[4] || title),
          emailStatus: String(row[5] || '')
        });
      }
    }

    return notices.reverse();
  } catch (err) {
    Logger.log('getNoticesList error: ' + err.toString());
    return [];
  }
}

// ৩.২. বর্তমান পিডিএফ নোট ও বইয়ের তালিকা রিটার্ন করা
function getMaterialsList() {
  try {
    autoSetupSheets();
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (!ss) return [];
    var sheet = ss.getSheetByName('Materials');
    if (!sheet) return [];
    var lastRow = sheet.getLastRow();
    if (lastRow <= 1) return [];

    var data = sheet.getRange(2, 1, lastRow - 1, 7).getValues();
    var materials = [];

    for (var i = 0; i < data.length; i++) {
      var row = data[i];
      var title = row[2] ? String(row[2]).trim() : '';
      var driveUrl = row[5] ? String(row[5]).trim() : '';
      if (title || driveUrl) {
        materials.push({
          rowIndex: i + 2,
          id: String(row[0] || ('mat-' + (i + 1))),
          courseCode: String(row[1] || 'PS-101').trim(),
          title: title || 'নোট / শিট',
          category: String(row[3] || 'হ্যান্ডনোট').trim(),
          author: String(row[4] || 'বিভাগীয় সংগ্রহ').trim(),
          driveUrl: driveUrl,
          fileSize: String(row[6] || '').trim()
        });
      }
    }

    return materials.reverse();
  } catch (err) {
    Logger.log('getMaterialsList error: ' + err.toString());
    return [];
  }
}

